pub trait StorageBackend {
    fn load(&self) -> Result<Store, String>;
    fn save(&self, store: &Store) -> Result<(), String>;
    fn append_log(&self, entries: &[LogEntry]) -> Result<(), String>;
    /// Latest Actual fact for one linked task, including its log ID for undo.
    fn latest_actual(&self, task_id: Id) -> Result<Option<LogEntry>, String>;
    fn completions_in_window(&self, from: DateTime<Utc>, to: DateTime<Utc>)
        -> Result<Vec<CompletionFact>, String>;
    fn recent_completions(&self, limit: usize) -> Result<Vec<CompletionFact>, String>;
}

/// Query extra facts so recent untagged completions do not exhaust prompt history.
pub fn build_history(
    backend: &dyn StorageBackend,
    store: &Store,
    limit: usize,
) -> Result<Vec<ubu_core::CompletedExample>, String> {
    let facts = backend.recent_completions(limit.saturating_mul(4))?;
    Ok(ubu_core::recent_completed_examples(store, &facts, limit))
}

fn completion_fact(entry: &LogEntry) -> Option<CompletionFact> {
    match &entry.kind {
        ubu_core::LogEntryKind::Fact(ubu_core::FactKind::Actual {
            item_id, status: ubu_core::ActualStatus::Done, actual,
        }) => Some(CompletionFact { item_id: *item_id, at: entry.at, actual: actual.clone() }),
        _ => None,
    }
}

fn actual_item_id(entry: &LogEntry) -> Option<Id> {
    match &entry.kind {
        ubu_core::LogEntryKind::Fact(ubu_core::FactKind::Actual { item_id, .. }) => Some(*item_id),
        _ => None,
    }
}

fn undone_completion(entry: &LogEntry) -> Option<(Id, Id)> {
    match &entry.kind {
        ubu_core::LogEntryKind::Command(ubu_core::CommandKind::UndoCompletion { task_id, completion_id }) => Some((*task_id, *completion_id)),
        _ => None,
    }
}

/// Query only tasks eligible for Calendar's existing 24-hour correction rule.
/// Storage access stays outside gcal's pure reconciliation function.
pub(crate) fn calendar_actuals(
    backend: &dyn StorageBackend, store: &Store, events: &[gcal::FetchedEvent], now: DateTime<Utc>,
) -> Result<std::collections::BTreeMap<Id, LogEntry>, String> {
    let candidates: std::collections::BTreeSet<_> = events.iter()
        .filter(|event| event.color_id.is_none() && event.end > now - chrono::Duration::hours(24))
        .map(|event| event.id.as_str()).collect();
    let mut actuals = std::collections::BTreeMap::new();
    for (task_id, event_id) in &store.calendar_links {
        if candidates.contains(event_id.as_str()) && store.tasks.get(task_id)
            .is_some_and(|task| task.pinned.is_none() && task.status == ubu_core::TaskStatus::Done) {
            if let Some(entry) = backend.latest_actual(*task_id)? { actuals.insert(*task_id, entry); }
        }
    }
    Ok(actuals)
}

/// Retained JSON backend for compatibility tests and callers of the storage trait.
#[allow(dead_code)]
pub struct JsonBackend {
    pub path: PathBuf,
}

#[allow(dead_code)] // The production CLI selects SQLite; JSON remains a compatibility backend.
impl JsonBackend {
    // Keep the log separate so loading/saving Store never reads historical rows.
    fn log_path(&self) -> PathBuf {
        let mut path = self.path.as_os_str().to_os_string();
        path.push(".log.json");
        PathBuf::from(path)
    }

    fn load_log(&self) -> Result<Vec<LogEntry>, String> {
        let path = self.log_path();
        match fs::read_to_string(&path) {
            Ok(contents) => serde_json::from_str(&contents)
                .map_err(|error| format!("failed to parse {}: {error}", path.display())),
            Err(error) if error.kind() == ErrorKind::NotFound => Ok(Vec::new()),
            Err(error) => Err(format!("failed to read {}: {error}", path.display())),
        }
    }
}

impl StorageBackend for JsonBackend {
    fn load(&self) -> Result<Store, String> {
        load(&self.path)
    }

    fn save(&self, store: &Store) -> Result<(), String> {
        save(&self.path, store)
    }

    fn append_log(&self, entries: &[LogEntry]) -> Result<(), String> {
        let mut log = self.load_log()?;
        let mut ids: std::collections::BTreeSet<_> = log.iter().map(|entry| entry.id).collect();
        for entry in entries {
            if ids.insert(entry.id) {
                log.push(entry.clone());
            }
        }
        save_json(&self.log_path(), serde_json::to_string_pretty(&log))
    }

    fn latest_actual(&self, task_id: Id) -> Result<Option<LogEntry>, String> {
        let log = self.load_log()?;
        let mut ids = std::collections::BTreeSet::new();
        Ok(log.iter().enumerate().filter(|(_, entry)| ids.insert(entry.id))
            .filter(|(_, entry)| actual_item_id(entry) == Some(task_id))
            .max_by_key(|(index, entry)| (entry.at, *index))
            .map(|(_, entry)| entry.clone()))
    }

    fn completions_in_window(
        &self,
        from: DateTime<Utc>,
        to: DateTime<Utc>,
    ) -> Result<Vec<CompletionFact>, String> {
        Ok(json_completions(&self.load_log()?)
            .into_iter()
            .filter(|fact| from <= fact.at && fact.at < to)
            .collect())
    }

    fn recent_completions(&self, limit: usize) -> Result<Vec<CompletionFact>, String> {
        Ok(json_completions(&self.load_log()?)
            .into_iter()
            .rev()
            .take(limit)
            .collect())
    }
}

#[allow(dead_code)]
fn json_completions(log: &[LogEntry]) -> Vec<CompletionFact> {
    // Match SQLite's first-write-wins IDs, including duplicate IDs in legacy JSON.
    let mut ids = std::collections::BTreeSet::new();
            store.pending_decisions.iter().map(|entity| {
                serde_json::to_string(entity)
                    .map(|data| (entity.id.to_string(), data))
                    .map_err(|error| error.to_string())
            }),
        )?;
        rewrite(
            &tx,
            "calendar_links",
            "id, value",
            store
                .calendar_links
                .iter()
                .map(|(id, value)| Ok((id.to_string(), value.clone()))),
        )?;
        rewrite(
            &tx,
            "export_signatures",
            "id, value",
            store
                .export_signatures
                .iter()
                .map(|(id, value)| Ok((id.to_string(), value.clone()))),
        )?;
        rewrite(
            &tx,
            "category_colors",
            "category, color",
            store
                .category_colors
                .iter()
                .map(|(category, color)| Ok((category.clone(), color.clone()))),
        )?;
        rewrite(
            &tx,
            "singletons",
            "key, data",
            [
                ("preferences", serde_json::to_string(&store.preferences)),
                (
                    "decision_history",
                    serde_json::to_string(&store.decision_history),
                ),
                ("ollama_model", serde_json::to_string(&store.ollama_model)),
                ("poll_snapshot", serde_json::to_string(&store.poll_snapshot)),
                ("batch_passes", serde_json::to_string(&store.batch_passes)),
                ("clarify_sessions", serde_json::to_string(&store.clarify_sessions)),
                ("decomposition_history", serde_json::to_string(&store.decomposition_history)),
                ("pending_decompositions", serde_json::to_string(&store.pending_decompositions)),
                ("pending_event_deletions", serde_json::to_string(&store.pending_event_deletions)),
            ]
            .into_iter()
            .map(|(key, data)| {
                data.map(|data| (key.to_string(), data))
                    .map_err(|error| error.to_string())
            }),
        )?;

        tx.commit()
            .map_err(|error| format!("failed to commit SQLite save: {error}"))
    }

    fn append_log(&self, entries: &[LogEntry]) -> Result<(), String> {
        let tx = self.connection.unchecked_transaction()
            .map_err(|error| format!("failed to begin SQLite log append: {error}"))?;
        append_log_rows(&tx, entries)?;
        tx.commit().map_err(|error| format!("failed to commit SQLite log append: {error}"))
    }

    fn latest_actual(&self, task_id: ubu_core::Id) -> Result<Option<LogEntry>, String> {
        let data: Option<String> = self.connection.query_row(
            "SELECT log.data FROM log_actuals a JOIN log ON log.id = a.log_id WHERE a.item_id = ?1 ORDER BY a.at DESC, a.nanos DESC, a.rowid DESC LIMIT 1",
            [task_id.to_string()], |row| row.get(0),
        ).optional().map_err(|error| format!("failed to query latest SQLite actual: {error}"))?;
        data.map(|data| serde_json::from_str(&data)
            .map_err(|error| format!("invalid SQLite actual entry: {error}"))).transpose()
    }

    fn completions_in_window(&self, from: DateTime<Utc>, to: DateTime<Utc>) -> Result<Vec<CompletionFact>, String> {
        if from >= to { return Ok(vec![]); }
        // The existing index stores seconds. Widen the upper bound when needed,
        // then enforce exact subsecond boundaries using the retained JSON timestamp.
        let end = to.timestamp() + i64::from(to.timestamp_subsec_nanos() != 0);
        let completions = read_completions(&self.connection,
            "SELECT data FROM log WHERE is_completion = 1 AND NOT EXISTS (SELECT 1 FROM log_completion_undos u WHERE u.task_id = log.item_id AND u.completion_id = log.id) AND at >= ?1 AND at < ?2 ORDER BY at, rowid",
            params![from.timestamp(), end])?;
        Ok(completions.into_iter().filter(|fact| from <= fact.at && fact.at < to).collect())
    }

    fn recent_completions(&self, limit: usize) -> Result<Vec<CompletionFact>, String> {
        read_completions(&self.connection,
            "SELECT data FROM log WHERE is_completion = 1 AND NOT EXISTS (SELECT 1 FROM log_completion_undos u WHERE u.task_id = log.item_id AND u.completion_id = log.id) ORDER BY at DESC, rowid DESC LIMIT ?1",
            [i64::try_from(limit).unwrap_or(i64::MAX)])
    }
}

fn append_log_rows(connection: &Connection, entries: &[LogEntry]) -> Result<(), String> {
    let mut insert = connection.prepare(
        "INSERT OR IGNORE INTO log (id, at, data, item_id, is_completion) VALUES (?1, ?2, ?3, ?4, ?5)"
    ).map_err(|error| format!("failed to prepare SQLite log append: {error}"))?;
    for entry in entries {
        let data = serde_json::to_string(entry).map_err(|error| format!("failed to serialize log: {error}"))?;
        let item_id = completion_fact(entry).map(|fact| fact.item_id.to_string());
        let inserted = insert.execute(params![entry.id.to_string(), entry.at.timestamp(), data, item_id, i64::from(item_id.is_some())])
            .map_err(|error| format!("failed to append SQLite log: {error}"))?;
        if inserted != 0 { write_log_metadata(connection, entry)?; }
    }
    Ok(())
}

fn write_log_metadata(connection: &Connection, entry: &LogEntry) -> Result<(), String> {
    if let Some(item_id) = actual_item_id(entry) {
        connection.execute("INSERT OR IGNORE INTO log_actuals(log_id, item_id, at, nanos) VALUES (?1, ?2, ?3, ?4)",
            params![entry.id.to_string(), item_id.to_string(), entry.at.timestamp(), entry.at.timestamp_subsec_nanos()])
            .map_err(|error| format!("failed to index SQLite actual: {error}"))?;
    }
    if let Some((task_id, completion_id)) = undone_completion(entry) {
        connection.execute("INSERT OR IGNORE INTO log_completion_undos(task_id, completion_id) VALUES (?1, ?2)",
            params![task_id.to_string(), completion_id.to_string()])
            .map_err(|error| format!("failed to index SQLite completion undo: {error}"))?;
    }
    Ok(())
}

fn read_completions(connection: &Connection, sql: &str, params: impl rusqlite::Params) -> Result<Vec<CompletionFact>, String> {
    let mut statement = connection.prepare(sql).map_err(|error| format!("failed to prepare SQLite completion query: {error}"))?;
    let rows = statement.query_map(params, |row| row.get::<_, String>(0))
        .map_err(|error| format!("failed to query SQLite completions: {error}"))?;
    let mut completions = Vec::new();
    for row in rows {
        let data = row.map_err(|error| format!("failed to read SQLite completion: {error}"))?;
        let entry: LogEntry = serde_json::from_str(&data).map_err(|error| format!("invalid SQLite completion log entry: {error}"))?;
        if let Some(fact) = completion_fact(&entry) { completions.push(fact); }
    }
    Ok(completions)
}

// Identifiers here are internal constants, never user input.
fn rewrite(
    connection: &Connection,
    table: &str,
    columns: &str,
    rows: impl IntoIterator<Item = Result<(String, String), String>>,
) -> Result<(), String> {
    connection
        .execute(&format!("DELETE FROM {table}"), [])
    },
    EditDuration {
        task_id: Id,
        est_duration: chrono::Duration,
    },
    EditPin {
        task_id: Id,
        pinned: Option<TimeWindow>,
    },
    EditPref {
        pref: Preference,
