    UbuTimestamp::parse(&record.updated_at)?;
    validate_object_version(record)?;
    validate_task_lifecycle_status(record)?;
    validate_canonical_object_payload(record)?;
    serde_json::to_string(&record.payload)?;
    Ok(())
}

