#[tokio::test]
async fn cross_writer_key_is_global_per_device() {
    let store = UbuStore::in_memory().await.unwrap();
    // A LogEntry canonical object deliberately uses the same id kind as a logs
    // row, testing that table ownership cannot be inferred from the prefix alone.
    let id = UbuId::new(ObjectType::LogEntry);
    let payload = json!({"id": id.as_str(), "authority_source": "user", "fact": "object"});
    let object = ubu_store::models::object_record::NewObjectRecord {
        id: id.to_string(),
        object_type: "LogEntry".into(),
        version: 1,
        status: "active".into(),
        compartment_label: "default".into(),
        payload: payload.clone(),
        created_at: "2026-09-19T02:00:00Z".into(),
        updated_at: "2026-09-19T02:00:00Z".into(),
    };
    let envelope = common::envelope_for(id.as_str(), ubu_core::VersionRef::Absent);
    let admitted = queries::admit_object(store.pool(), &envelope, object)
        .await
        .unwrap();
    let ledger = common::ledger(store.pool()).await;
    let mut log = log_record();
    log.id = id.to_string();
    let error = queries::append_log_entry(store.pool(), &envelope, log.clone())
        .await
        .unwrap_err();
    assert!(matches!(
        error,
        ubu_store::StoreError::Core(ubu_core::UbuError::IdempotencyKeyConflict { .. })
    ));
    log.payload = payload;
    let error = queries::append_log_entry(store.pool(), &envelope, log)
        .await
        .unwrap_err();
    assert!(matches!(
        error,
        ubu_store::StoreError::ReplayTargetMismatch {
            expected_table: "logs",
            ..
        }
    ));
    assert!(logs(&store).await.is_empty());
    assert_eq!(common::ledger(store.pool()).await, ledger);

fn validate_canonical_object_payload(record: &NewObjectRecord) -> Result<()> {
    let payload = record
        .payload
        .as_object()
        .ok_or_else(|| invalid_payload("canonical object payload must be a JSON object"))?;

    let payload_id = payload
        .get("id")
        .and_then(Value::as_str)
        .ok_or_else(|| invalid_payload("canonical object payload must include id"))?;
    validate_object_id_for_type(payload_id, &record.object_type)?;
    if payload_id != record.id {
        return Err(invalid_payload(
            "canonical object payload id must match admitted object id",
        ));
    }

    let object_type = object_type_from_str(&record.object_type)?;
    validate_payload_lifecycle_status(record, payload)?;
    validate_task_fields(object_type, payload)?;
    validate_objective_fields(object_type, payload)?;
    validate_payload_provenance(object_type, payload)?;
    if object_type == ObjectType::Preference {
        let preference: Preference = serde_json::from_value(record.payload.clone())?;
        preference.validate()?;
    }
    validate_payload_authority_source(object_type, payload)?;
    validate_payload_compartment_metadata(object_type, payload)?;

    Ok(())
}

fn validate_objective_fields(object_type: ObjectType, payload: &Map<String, Value>) -> Result<()> {
    use ubu_core::core::{
        validate_objective_routine_fields, ObjectiveMode, RecurrenceSchedule,
        RoutineInstanceTemplate,
    };
    if object_type != ObjectType::Objective {
        return Ok(());
    }
    let mode: ObjectiveMode = payload
        .get("mode")
        .map(|v| serde_json::from_value(v.clone()))
        .transpose()?
        .unwrap_or_default();
    let recurrence: Option<RecurrenceSchedule> = payload
        .get("recurrence")
        .map(|v| serde_json::from_value(v.clone()))
        .transpose()?;
    let template: Option<RoutineInstanceTemplate> = payload
        .get("routine_instance_template")
        .map(|v| serde_json::from_value(v.clone()))
        .transpose()?;
    if let Some(schedule) = &recurrence {
        schedule.validate()?;
    }
    if let Some(template) = &template {
        template.validate()?;
    }
    let id: UbuId = serde_json::from_value(payload["id"].clone())?;
    validate_objective_routine_fields(
        &id,
        mode,
        envelope: MutationEnvelope,
        record: NewObjectRecord,
    },
    Log {
        envelope: MutationEnvelope,
        record: NewLogRecord,
    },
}

/// The admitted result of one `BatchWrite`, in request order.
#[derive(Debug, Clone)]
pub enum BatchResult {
    Object(ObjectRecord),
    Log(LogRecord),
}

impl BatchResult {
    pub fn as_object(&self) -> Option<&ObjectRecord> {
        match self {
            Self::Object(record) => Some(record),
            Self::Log(_) => None,
        }
    }
    pub fn as_log(&self) -> Option<&LogRecord> {
        match self {
            Self::Log(record) => Some(record),
            Self::Object(_) => None,
        }
    }
}

/// Atomically admit ordered canonical writes. Later preconditions observe
/// earlier writes. Replay retains the ordinary writers' current-state semantics.
/// Only this outer writer owns commit or rollback; no transaction escapes it.
pub async fn admit_batch(pool: &SqlitePool, writes: Vec<BatchWrite>) -> Result<Vec<BatchResult>> {
    let mut transaction = crate::transactions::begin(pool).await?;
    let result = async {
        let mut seen = std::collections::HashSet::new();
        let mut results = Vec::with_capacity(writes.len());
        for write in writes {
            let envelope = match &write {
                BatchWrite::Object { envelope, .. } | BatchWrite::Log { envelope, .. } => envelope,
            };
            // prepare_mutation intentionally permits same-payload replay. Within
            // one request, even identical repeated keys are a caller error.
            if !seen.insert(envelope.mutation_key()) {
                return Err(ubu_core::UbuError::IdempotencyKeyConflict {
                    origin_device_id: envelope.origin_device_id.as_str().to_owned(),
                    idempotency_key: envelope.idempotency_key.as_str().to_owned(),
                }
                .into());
            }
            results.push(match write {
                BatchWrite::Object { envelope, record } => {
                    let prepared = prepare_mutation(
                        &mut transaction,
                        &envelope,
                        &record.payload,
                        MutationTarget::Object,
                    )
                    .await?;
                    BatchResult::Object(
                        admit_prepared_object(&mut transaction, &envelope, record, prepared)
                            .await?,
                    )
                }
                BatchWrite::Log { envelope, record } => {
                    let prepared = prepare_mutation(
                        &mut transaction,
                        &envelope,
                        &record.payload,
                        MutationTarget::Log,
                    )
                    .await?;
                    BatchResult::Log(
                        append_prepared_log(&mut transaction, &envelope, record, prepared).await?,
                    )
                }
            });
        }
        Ok(results)
    }
    .await;
    finish_mutation(transaction, result).await
}

/// Canonical admission audit view. Candidate-only requests contain review data
/// and are excluded; the private replay lookup still sees all Device-global keys.
    // A LogEntry canonical object deliberately uses the same id kind as a logs
    // row, testing that table ownership cannot be inferred from the prefix alone.
    let id = UbuId::new(ObjectType::LogEntry);
    let payload = json!({"id": id.as_str(), "authority_source": "user", "fact": "object"});
    let object = ubu_store::models::object_record::NewObjectRecord {
        id: id.to_string(),
        object_type: "LogEntry".into(),
        version: 1,
        status: "active".into(),
        compartment_label: "default".into(),
        payload: payload.clone(),
        created_at: "2026-09-19T02:00:00Z".into(),
        updated_at: "2026-09-19T02:00:00Z".into(),
    };
    let envelope = common::envelope_for(id.as_str(), ubu_core::VersionRef::Absent);
    let admitted = queries::admit_object(store.pool(), &envelope, object)
        .await
        .unwrap();
    let ledger = common::ledger(store.pool()).await;
    let mut log = log_record();
    log.id = id.to_string();
    let error = queries::append_log_entry(store.pool(), &envelope, log.clone())
        .await
        .unwrap_err();
    assert!(matches!(
        error,
        ubu_store::StoreError::Core(ubu_core::UbuError::IdempotencyKeyConflict { .. })
    ));
    log.payload = payload;
    let error = queries::append_log_entry(store.pool(), &envelope, log)
        .await
        .unwrap_err();
    assert!(matches!(
        error,
        ubu_store::StoreError::ReplayTargetMismatch {
            expected_table: "logs",
            ..
        }
    ));
    assert!(logs(&store).await.is_empty());
    assert_eq!(common::ledger(store.pool()).await, ledger);
    assert_eq!(
        queries::get_current_state(store.pool(), id.as_str())
            .await
            .unwrap(),
        Some(admitted)
    );
}
